from decimal import Decimal, InvalidOperation


def allocate_by_ratios(total: str, ratios: list) -> list[Decimal]:
    if not isinstance(total, str):
        raise ValueError("total must be a string")
    try:
        amount = Decimal(total)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid total: {total!r}") from None
    if not amount.is_finite():
        raise ValueError("total must be finite")
    tup = amount.as_tuple()
    exp = tup.exponent
    if not isinstance(exp, int) or exp < -2:
        raise ValueError("total must have at most 2 decimal places")
    int_digits = 0
    for d in tup.digits:
        int_digits = int_digits * 10 + d
    power = exp + 2
    if int_digits == 0:
        cents = 0
    else:
        cents = int_digits * pow(10, power)
    negative = amount < 0
    if not isinstance(ratios, list) or len(ratios) == 0:
        raise ValueError("ratios must be a non-empty list")
    weights = []
    for entry in ratios:
        if isinstance(entry, bool):
            raise ValueError("bool weights are not accepted")
        if isinstance(entry, int):
            weight = Decimal(entry)
        elif isinstance(entry, Decimal):
            weight = entry
        elif isinstance(entry, str):
            try:
                weight = Decimal(entry)
            except (InvalidOperation, ValueError):
                raise ValueError(f"invalid weight: {entry!r}") from None
        else:
            raise ValueError(f"invalid weight: {entry!r}")
        if not weight.is_finite():
            raise ValueError("weights must be finite")
        if weight < 0:
            raise ValueError("weights must be >= 0")
        weights.append(weight)
    decoded = []
    nonzero_exps = []
    for w in weights:
        wt = w.as_tuple()
        e = wt.exponent
        if w.is_zero():
            decoded.append((0, e, True))
        else:
            v = 0
            for d in wt.digits:
                v = v * 10 + d
            decoded.append((v, e, False))
            nonzero_exps.append(e)
    if not nonzero_exps:
        raise ValueError("at least one weight must be > 0")
    e_min = min(nonzero_exps)
    int_weights = []
    for v, e, is_zero in decoded:
        if is_zero:
            int_weights.append(0)
        else:
            if e_min < 0:
                int_weights.append(v * pow(10, e - e_min))
            else:
                int_weights.append(v * pow(10, e))
    total_w = sum(int_weights)
    if total_w <= 0:
        raise ValueError("at least one weight must be > 0")
    floors = []
    numers = []
    for wi in int_weights:
        if wi == 0:
            floors.append(0)
            numers.append(-1)
        else:
            prod = cents * wi
            floors.append(prod // total_w)
            numers.append(prod % total_w)
    remaining = cents - sum(floors)
    order = sorted(
        (i for i, wi in enumerate(int_weights) if wi > 0),
        key=lambda i: (-numers[i], -int_weights[i], i),
    )
    for i in order[:remaining]:
        floors[i] += 1
    parts = []
    for fc in floors:
        if fc == 0:
            parts.append(Decimal("0.00"))
        else:
            s = str(fc)
            digits_t = tuple(int(ch) for ch in s)
            sign = 1 if negative else 0
            parts.append(Decimal((sign, digits_t, -2)))
    return parts
